// ─── Bodyless chat panel ──────────────────────────────────────────────────────
interface Message { id: number; type: 'user' | 'ai' | 'loading'; text?: string; }

function BodylessChat({ onChipQuery }: { onChipQuery: string | null }) {
  const [messages, setMessages]   = useState<Message[]>([]);
  const [input, setInput]         = useState('');
  const [loading, setLoading]     = useState(false);
  const chatAreaRef               = useRef<HTMLDivElement>(null);
  const agentRef                  = useRef<SpotterAgentEmbed | null>(null);
  const counterRef                = useRef(0);
  const prevChipQuery             = useRef<string | null>(null);

  // Initialise agent once
  useEffect(() => {
    agentRef.current = new SpotterAgentEmbed({ worksheetId: THOUGHTSPOT_MODEL_ID });
  }, []);

  const appendVizContainer = useCallback((msgId: number, container: HTMLDivElement) => {
    const slot = document.getElementById(`lumira-viz-${msgId}`);
    if (slot) {
      slot.innerHTML = '';
      container.style.width = '100%';
      slot.appendChild(container);
    }
  }, []);

  const send = useCallback(async (query: string) => {
    if (!query.trim() || loading || !agentRef.current) return;
    const uid = ++counterRef.current;
    const aid = ++counterRef.current;

    setMessages(prev => [...prev, { id: uid, type: 'user', text: query }]);
    setMessages(prev => [...prev, { id: aid, type: 'loading' }]);
    setLoading(true);

    const result = await agentRef.current.sendMessage(query);
    setLoading(false);

    setMessages(prev =>
      prev.map(m => m.id === aid ? { ...m, type: 'ai' as const } : m)
    );

    if (result && !result.error && result.container) {
      // Short delay so the AI message slot is rendered
      setTimeout(() => appendVizContainer(aid, result.container as HTMLDivElement), 50);
    }
  }, [loading, appendVizContainer]);

  // Respond to chip clicks from the parent
  useEffect(() => {
    if (onChipQuery && onChipQuery !== prevChipQuery.current) {
      prevChipQuery.current = onChipQuery;
      send(onChipQuery);
    }
  }, [onChipQuery, send]);

  // Auto-scroll on new messages
  useEffect(() => {
    if (chatAreaRef.current) {
      chatAreaRef.current.scrollTop = chatAreaRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    send(input);
    setInput('');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>

      {/* Header */}
      <div style={{
        padding: '1rem 1.25rem',
        borderBottom: `1px solid ${BORDER}`,
        display: 'flex', alignItems: 'center', gap: 10,
        flexShrink: 0, backgroundColor: '#FFFFFF',
      }}>
        <LumiraGem size={28} />
        <div>
          <div style={{ fontSize: 14, fontWeight: 700, color: NAVY, letterSpacing: '-0.01em' }}>Lumira AI</div>
          <div style={{ fontSize: 11, color: INK2 }}>Commerce intelligence · ask anything</div>
        </div>
        <div style={{
          marginLeft: 'auto', width: 8, height: 8, borderRadius: '50%',
          backgroundColor: '#16a34a', boxShadow: '0 0 0 3px rgba(22,163,74,0.20)',
        }} />
      </div>

      {/* Welcome (shown when no messages) */}
      {messages.length === 0 && (
        <div style={{
          padding: '1.5rem 1.25rem',
          borderBottom: `1px solid ${BORDER}`,
          backgroundColor: BG,
          flexShrink: 0,
        }}>
          <p style={{ fontSize: 13, color: INK2, lineHeight: 1.65, margin: 0 }}>
            Ask me anything about your sales, inventory, channels, and suppliers —
            or ask a general question about Lumira. I'll chart live data instantly.
          </p>
        </div>
      )}

      {/* Messages */}
      <div
        ref={chatAreaRef}
        style={{
          flex: 1, overflowY: 'auto', padding: '1rem 1rem',
          display: 'flex', flexDirection: 'column', gap: 12,
          backgroundColor: '#FAFBFF',
        }}
      >
        {messages.map(msg => (
          <div key={msg.id} style={{
            display: 'flex',
            flexDirection: msg.type === 'user' ? 'row-reverse' : 'row',
            alignItems: 'flex-start', gap: 8,
          }}>
            {/* Avatar */}
            {msg.type !== 'user' && (
              <div style={{
                width: 26, height: 26, borderRadius: '50%',
                backgroundColor: BG2, border: `1px solid ${BORDER}`,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                flexShrink: 0, marginTop: 2,
              }}>
                <LumiraGem size={14} />
              </div>
            )}

            {/* Bubble */}
            <div style={{
              maxWidth: '85%',
              backgroundColor: msg.type === 'user' ? BLUE : '#FFFFFF',
              color: msg.type === 'user' ? '#FFFFFF' : NAVY,
              borderRadius: msg.type === 'user' ? '14px 14px 2px 14px' : '14px 14px 14px 2px',
              padding: msg.type === 'loading' ? 0 : msg.type === 'user' ? '9px 13px' : '4px',
              fontSize: 13.5,
              lineHeight: 1.5,
              boxShadow: '0 1px 4px rgba(43,60,193,0.08)',
              border: msg.type !== 'user' ? `1px solid ${BORDER}` : 'none',
              overflow: 'hidden',
            }}>
              {msg.type === 'user'    && msg.text}
              {msg.type === 'loading' && <TypingDots />}
              {msg.type === 'ai'      && (
                <div
                  id={`lumira-viz-${msg.id}`}
                  style={{ minHeight: 80, width: '100%' }}
                />
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Input */}
      <form
        onSubmit={handleSubmit}
        style={{
          padding: '0.75rem 1rem',
          borderTop: `1px solid ${BORDER}`,
          backgroundColor: '#FFFFFF',
          display: 'flex', gap: 8, alignItems: 'center',
          flexShrink: 0,
        }}
      >
        <input
          value={input}
          onChange={e => setInput(e.target.value)}
          placeholder="Ask a follow up..."
          disabled={loading}
          style={{
            flex: 1,
            padding: '9px 13px',
            borderRadius: 22,
            border: `1px solid ${BORDER}`,
            fontSize: 13,
            color: NAVY,
            backgroundColor: BG,
            outline: 'none',
            fontFamily: "'Inter', -apple-system, sans-serif",
          }}
        />
        <button
          type="submit"
          disabled={loading || !input.trim()}
          style={{
            width: 36, height: 36, borderRadius: '50%',
            backgroundColor: loading || !input.trim() ? BG2 : BLUE,
            border: 'none', cursor: loading || !input.trim() ? 'default' : 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            flexShrink: 0, transition: 'background 0.15s',
          }}
        >
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none"
            stroke={loading || !input.trim() ? INK2 : '#FFFFFF'}
            strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
            <line x1="22" y1="2" x2="11" y2="13" />
            <polygon points="22 2 15 22 11 13 2 9 22 2" />
          </svg>
        </button>
      </form>
    </div>
  );
}

